// FilterTargets: 從當前選中的 targets 中移除非不死生物（優先讀取 actor.system.details.type.value）
(async () => {
  const targets = Array.from(game.user.targets);
  if (!targets.length) return ui.notifications.warn("請先選中一個或多個目標（使用 Target 工具），然後再運行此宏。");

  // 可靠讀取 creature type 的函數，優先用 actor.system.details.type.value
  function readCreatureType(actor) {
    if (!actor) return null;
    // 優先路徑（與你提供的輸出一致）
    const primary = actor?.system?.details?.type?.value ?? actor?.system?.details?.type;
    if (typeof primary === "string" && primary.trim()) return primary.trim().toLowerCase();
    // 回退至 prototypeToken.actorData（如果存在）
    const proto = actor?.prototypeToken?.actorData?.details?.type?.value ?? actor?.prototypeToken?.actorData?.details?.type;
    if (typeof proto === "string" && proto.trim()) return proto.trim().toLowerCase();
    // 進一步回退：getRollData 也可能包含 details
    if (typeof actor.getRollData === "function") {
      try {
        const rd = actor.getRollData();
        const rdType = rd?.details?.type;
        if (typeof rdType === "string" && rdType.trim()) return rdType.trim().toLowerCase();
      } catch (e) { /* ignore */ }
    }
    return null;
  }

  const removed = [];
  const kept = [];

  for (const t of targets) {
    try {
      // t 可能是 Canvas Token 或 TokenDocument 或其他。盡力解析到 canvas Token 和 actor
      let token = null;
      if (t?.document && canvas.tokens.get(t.id)) token = canvas.tokens.get(t.id);
      else if (t?.id && canvas.tokens.get(t.id)) token = canvas.tokens.get(t.id);
      else token = t; // 也有可能已經是 canvas token

      // 最終確保拿到 actor
      const actor = token?.actor ?? (await fromUuid(token?.actor?.uuid).catch(()=>null)) ?? null;
      if (!actor) {
        console.warn("無法解析目標 actor：", t);
        continue;
      }

      const ctype = readCreatureType(actor); // e.g. "undead", "humanoid"
      const isUndead = !!ctype && (ctype.includes("fiend") || ctype.includes("fey"));
      if (!isUndead) {
        // 取消目標：優先用 canvas token 的 setTarget 方法
        try {
          if (token && typeof token.setTarget === "function") {
            token.setTarget(false, { user: game.user.id });
          } else {
            // 回退：刪除 game.user.targets 中的條目
            game.user.targets.delete(t);
            // 另一回退：嘗試找畫布上對應 token 並取消
            const canvasToken = canvas.tokens.placeables.find(p => p.actor?.id === actor.id);
            if (canvasToken && typeof canvasToken.setTarget === "function") canvasToken.setTarget(false, { user: game.user.id });
          }
        } catch (e) {
          // 最終回退：直接從 Set 中刪除
          try { game.user.targets.delete(t); } catch(e2) { /* ignore */ }
        }
        removed.push(actor.name ?? token?.name ?? t?.id);
      } else {
        kept.push(actor.name ?? token?.name ?? t?.id);
      }
    } catch (err) {
      console.error("處理目標時出錯：", err);
    }
  }

  // 輸出結果
  const removedText = removed.length ? removed.join(", ") : "（無）";
  const keptText = kept.length ? kept.join(", ") : "（無）";
})();
